+        return jar;
+    }
+
+    private static ModuleLayer createLayerForJar(Path jar, String moduleName) {
+        Configuration cf = ModuleLayer.boot().configuration().resolve(ModuleFinder.of(jar), ModuleFinder.of(), Set.of(moduleName));
